        print("YES")
        return

    for ta in range(a[1]):
        tmp = a[2] - ta * a[4]
        if tmp == a[0]:
            print("YES")
            return

    for tb in range(a[1]):
        tmp = a[3] - tb * a[5]
        if tmp == a[0]:
            print("YES")
            return

    for ta in range(a[1]):
        for tb in range(a[1]):
            tmp = (a[2] - ta * a[4]) + (a[3] - tb * a[5])
            if tmp == a[0]:
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
    main()

